        "title": "Creator Marketplace AI persona discovery",
        "background": "Creator marketplaces often begin with embeddings from bios, content topics, audience engagement, and past campaign fit. Clustering turns those embeddings into draft personas that humans can name, such as B2B thought leaders or career-transition coaches.",
        "numbers": "If 12,000 creators are embedded and $k=8$, an even split would average 1,500 creators per persona. A real run with cluster sizes 2,400, 1,900, 1,700, 1,400, 1,300, 1,100, 1,000, and 1,200 has entropy $-\\sum p_j\\log p_j\\approx2.05$, close to $\\log 8=2.08$, so it is not dominated by one bucket."
